CM_PUBLIC_URL = 'https://keewulninyoeylgflshb.supabase.co'
CM_PUBLIC_KEY = 'sb_publishable_iud9MpcZSxZHzSczRTIDqg_4BNZWQ8g'
CM_SOURCE_KEYS = ('kotoba','soroban','geometry','english')
